<x-app-layout><x-slot name="header"><h1 class="text-xl font-bold">Receive Add</h1></x-slot><form method="POST" action="{{route('goods-receipts.store')}}" x-data="receiptForm()">@csrf<section class="rounded border bg-white p-6"><h2 class="border-b pb-3 text-lg">General Info</h2><div class="mt-5 grid gap-5 md:grid-cols-2"><label>MRR date<input name="mrr_date" type="date" value="{{now()->format('Y-m-d')}}" class="mt-2 block w-full rounded border-slate-300"></label><label>MRR No<input readonly value="{{$nextNo}}" class="mt-2 block w-full rounded border-slate-200 bg-slate-100"></label><label>Payment Mode<select name="payment_mode" class="mt-2 block w-full rounded border-slate-300"><option value="cash">Cash</option><option value="credit">Credit</option><option value="bank">Bank</option></select></label><label>Cash Head<input name="cash_head" class="mt-2 block w-full rounded border-slate-300" placeholder="[Select]"></label><label>Purchase Type<select name="purchase_type" class="mt-2 block w-full rounded border-slate-300"><option value="local">Local</option><option value="import">Import</option></select></label><label>Supplier<select name="supplier_id" required class="mt-2 block w-full rounded border-slate-300"><option value="">[Select]</option>@foreach($suppliers as $s)<option value="{{$s->id}}">{{$s->name}}</option>@endforeach</select></label><label>Currency<select name="currency" class="mt-2 block w-full rounded border-slate-300"><option>BDT</option><option>USD</option></select></label><label>Ex Rate<input name="exchange_rate" value="1" type="number" min="0" step=".0001" class="mt-2 block w-full rounded border-slate-300"></label><label>Store<select name="store_id" x-model="storeId" required class="mt-2 block w-full rounded border-slate-300"><option value="">[Select]</option>@foreach($stores as $s)<option value="{{$s->id}}">{{$s->name}}</option>@endforeach</select></label><label>PO NO<input name="po_no" class="mt-2 block w-full rounded border-slate-300" placeholder="[Select PONO]"></label><label class="md:col-span-2">Remarks<textarea name="remarks" rows="2" class="mt-2 block w-full rounded border-slate-300"></textarea></label></div></section><section class="mt-5 overflow-hidden rounded border border-sky-200 bg-white"><div class="bg-sky-500 px-4 py-2 font-semibold text-white">Parts Line</div><div class="overflow-x-auto"><table class="w-full min-w-[1000px] text-sm"><thead class="bg-sky-50"><tr><th>Store Position</th><th>Item No</th><th>Item</th><th>Receive Qty</th><th>Unit</th><th>Rate</th><th>Amount</th><th>Landed Cost</th><th></th></tr></thead><tbody><template x-for="(line,i) in lines" :key="i"><tr class="border-t"><td class="p-1"><select x-model="line.position" :name="`items[${i}][store_position_id]`" class="w-full border"><option value="">Please Select</option><template x-for="p in positions.filter(p=>String(p.store_id)===String(storeId))"><option :value="p.id" x-text="p.name"></option></template></select></td><td class="p-1"><input x-model="line.part" @input="match(line)" :list="`receipt-products-${i}`" class="w-full border"><datalist :id="`receipt-products-${i}`"><template x-for="p in products"><option :value="p.part_no" x-text="`${p.part_no} — ${p.name}`"></option></template></datalist><input type="hidden" :name="`items[${i}][product_id]`" x-model="line.product"></td><td class="p-1"><input x-model="line.name" readonly class="w-full border bg-slate-50"></td><td class="p-1"><input x-model.number="line.qty" :name="`items[${i}][quantity]`" type="number" min=".01" step=".01" class="w-full border"></td><td class="p-1"><input x-model="line.unit" readonly class="w-full border bg-slate-50"></td><td class="p-1"><input x-model.number="line.rate" :name="`items[${i}][rate]`" type="number" min="0" step=".01" class="w-full border"></td><td class="p-1"><input :value="(line.qty*line.rate).toFixed(2)" readonly class="w-full border bg-slate-50"></td><td class="p-1"><input :value="(line.qty*line.rate).toFixed(2)" readonly class="w-full border bg-slate-50"></td><td><button type="button" @click="remove(i)" x-show="lines.length>1" class="text-rose-600">×</button></td></tr></template></tbody></table></div><button type="button" @click="add" class="m-3 rounded bg-sky-100 px-3 py-2 text-sky-800">+ Add row</button><div class="border-t p-3 text-right font-semibold">T.Order Qty <span x-text="lines.reduce((a,x)=>a+(Number(x.qty)||0),0)"></span> &nbsp; T.Cost ৳<span x-text="lines.reduce((a,x)=>a+(Number(x.qty)||0)*(Number(x.rate)||0),0).toFixed(2)"></span></div></section><div class="mt-6 flex gap-3"><button class="rounded bg-[#1f7d88] px-5 py-2.5 text-white">Save</button><a href="{{route('goods-receipts.index')}}" class="crm-cancel-button rounded px-5 py-2.5">Cancel</a></div></form><script>function receiptForm(){return{products:@json($products),positions:@json($positions),storeId:'',lines:[{position:'',part:'',product:'',name:'',unit:'',qty:0,rate:0}],add(){this.lines.push({position:'',part:'',product:'',name:'',unit:'',qty:0,rate:0})},remove(i){this.lines.splice(i,1)},match(l){let q=l.part.toLowerCase(),p=this.products.find(x=>x.part_no?.toLowerCase()===q||`${x.part_no} — ${x.name}`.toLowerCase()===q);if(p)Object.assign(l,{part:p.part_no,product:p.id,name:p.name,unit:p.unit});else Object.assign(l,{product:'',name:'',unit:''})}}}</script></x-app-layout>
